package org.rmaos.mingx;
import java.util.Random;
public final class MiniGXGameStateStress {
 private static void check(boolean ok,String msg){if(!ok)throw new AssertionError(msg);}
 private static void equal(MiniGXGameState a,MiniGXGameState b){check(a.objectId().equals(b.objectId()),"id drift");check(a.status().equals(b.status()),"status drift");check(a.lastWay().equals(b.lastWay()),"way drift");check(a.score()==b.score(),"score drift");check(a.combo()==b.combo(),"combo drift");check(a.uniqueWays()==b.uniqueWays(),"unique way drift");check(Math.abs(a.integrity()-b.integrity())<1e-7,"integrity drift");}
 public static void main(String[]args){MiniGXGameState a=new MiniGXGameState(),b=new MiniGXGameState();Random r=new Random(0x5EED114L);long prev=0;for(int i=0;i<250000;i++){int op=r.nextInt(16);if(op<12){a.pulse(op);b.pulse(op);}else if(op<14){a.reverse();b.reverse();}else{a.homeward();b.homeward();}equal(a,b);check(a.objectId().startsWith("CYC:MGX:"),"bad id");check(a.integrity()>=0f&&a.integrity()<=1f,"integrity range");check(a.uniqueWays()>=0&&a.uniqueWays()<=12,"unique ways range");check(a.combo()>=1&&a.combo()<=12,"combo range");check(a.score()>=prev,"score regressed");prev=a.score();check(a.status().equals("GENERATED")||a.status().equals("EMBER")||a.status().equals("ASH")||a.status().equals("SURVIVOR"),"bad status");}check(a.ash()>0,"no ASH reached");check(a.ember()>0,"no EMBER reached");check(a.survivor()>0,"no SURVIVOR reached");System.out.println("MINIGX_GAME_STATE_STRESS=PASS ops=250000 score="+a.score()+" ash="+a.ash()+" ember="+a.ember()+" survivor="+a.survivor());}
}
